  // rough cost of work sent straight to Google (images: per output image + input images; Omni video: ~$0.10/s)
  googleCost(engine, s = {}, inputs = 0) {
    if (engine === "omni-flash") return 0.1 * (+s.duration || 6);
    const e = this.imageEngines.find((x) => x.id === engine);
    if (!e || !e.g) return 0;
    return (+s.num_images || 1) * (e.g[s.resolution] || e.g["2K"]) + (inputs * 560 * e.g.in) / 1e6;
  },
