// stroke weight stays the same however small a part is drawn
const nsk = (s) => s.replace(/<(path|circle|rect|ellipse|line|polyline|polygon)\b/g, '<$1 vector-effect="non-scaling-stroke"');
// "#16171a" marks cut-outs: they take the tile's own background colour (--tilebg) so they read as gaps
const cut = (s) => s.replace(/fill="#16171a"/g, 'style="fill:var(--tilebg,#161617)"').replace(/stroke="#16171a"/g, 'style="stroke:var(--tilebg,#161617)"');
const svg = (body) => `<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${cut(nsk(body))}</svg>`;
// a part at (x, y) at scale s; a "-" before the name mirrors it left-right
const put = ([name, x = 0, y = 0, s = 1]) => {
  const flip = name[0] === "-", n = flip ? name.slice(1) : name, body = P[n];
  if (body == null) { console.warn("picons: no part", n); return ""; }
  return `<g transform="translate(${x} ${y}) scale(${s})${flip ? " translate(48 0) scale(-1 1)" : ""}">${body}</g>`;
};
// a dark disc behind a badge so it reads clearly where it overlaps the main picture
const disc = (cx, cy, r) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="#16171a" stroke="none"/>`;
const C = (...parts) => svg(parts.map((p) => (typeof p === "string" ? (P[p] != null ? P[p] : p) : put(p))).join(""));
// main picture with a small badge at the top right
