    const nn = nodes[0], keep = () => [nn, ...V.parents(nn.id).slice(0, 1), ...(V.cmpPartner && V.cmpPartner.id ? [V.node(V.cmpPartner.id)] : [])].filter((x, i, a) => x && x.id && a.indexOf(x) === i && V.node(x.id));
