          if (first) { first = false; let h = null; try { h = JSON.parse(/\}$/.test(ln) ? ln : ln + "}"); } catch (e) {} if (!h || h.app !== "Clarman VizLab backup") throw new Error(NOT); if (/\}$/.test(ln)) { for (const s of STORES) for (const r of h[s] || []) await merge(s, r); } return; }
          if (ln === "]" || ln === "}") { store = ln === "]" ? null : store; return; }
          const m = /^,"(\w+)":\[$/.exec(ln); if (m) { store = m[1]; return; }
          if (!store) throw new Error(NOT);
