async function addFiles(files, cx, cy) {
  const items = [];
  for (const f of files) {
    const name = f.name.replace(/\.[^.]+$/, "").slice(0, 30);
    if (f.type === "application/pdf" || /\.pdf$/i.test(f.name)) { // drawings: each page becomes an image node
      V.toast(`Reading ${f.name}…`, false, 3000);
      try {
        const { pages, total } = await V.pdfPages(f);
        pages.forEach((p) => items.push([p.dataUrl, total > 1 ? `${name} p${p.page}` : name, { pdf: true }]));
        if (total > pages.length) V.toast(`Added the first ${pages.length} of ${total} pages`, false, 5000);
      } catch (e) { V.toast(`Couldn't read ${f.name}: ${e.message}`, true, 7000); }
      continue;
    }
    if (!f.type.startsWith("image/")) continue;
    items.push([await V.fileToDataUrl(f), name, null]);
  }
  if (!items.length) return;
  const k = items.length, rows = Math.ceil(k / 5), cols = Math.ceil(k / rows), SX = V.NODE_W + 40, SY = V.NODE_H + 24;
  const [wx, wy] = cx != null ? toWorld(cx, cy) : V.viewCenter();
  const [fx, fy] = cx == null && V.G.nodes.some((n) => !V.isHidden(n.id) && !V.parents(n.id).length) ? V.nextSourceSpot(cols * SX - 40, rows * SY - 24) // (C1: beside the last picture added)
    : V.freeSpot(cx != null ? wx : wx - ((cols - 1) * SX) / 2, cx != null ? wy : wy - ((rows - 1) * SY) / 2, cols * SX - 40, rows * SY - 24);
  items.forEach(([url, label, ex], i) => V.addImageNode(url, [fx + (i % cols) * SX, fy + Math.floor(i / cols) * SY], label, ex)); // (each is on the canvas straight away; its upload carries on)
  const x1 = fx - V.NODE_W / 2, y1 = fy - V.NODE_H / 2;
  if (V.visibleNodes().length > 3) showBox(x1, y1, x1 + cols * SX - 40, y1 + rows * SY - 24);
  if (items.some((it) => it[2] && it[2].pdf) && V.drawingBriefs) setTimeout(() => V.drawingBriefs(), 400); // v3.69 T5 (A4, media.js): the briefs for drawings
}
cv.addEventListener("dragover", (e) => { e.preventDefault(); cv.classList.add("dropping"); });
cv.addEventListener("dragleave", () => cv.classList.remove("dropping"));
cv.addEventListener("drop", (e) => { e.preventDefault(); cv.classList.remove("dropping"); addFiles([...e.dataTransfer.files], e.clientX, e.clientY); });
document.addEventListener("paste", (e) => {
  if ((e.target instanceof Element && e.target.matches("textarea,input,[contenteditable]")) || !V.canvasShown()) return; // not on another page (the Library takes its own) or behind a pop-up
  const files = [...(e.clipboardData?.items || [])].filter((x) => x.type.startsWith("image/")).map((x) => x.getAsFile());
  if (files.length) { addFiles(files); V.toast("Picture pasted"); }
});
