  flatCtx(r.left, r.top, [["50%", () => V.zoomTo(0.5)], ["100%", () => V.zoomTo(1), "1"], ["200%", () => V.zoomTo(2)], "-", ["Fit everything", () => V.fit(), "F"], sel.length ? ["Fit the selection", () => V.fit(sel), "F"] : null].filter(Boolean));
