    const ctx = $("#ctx"), r = $("#tCapture").getBoundingClientRect(); ctx.innerHTML = "";
    on.forEach((x) => ctx.append(h("button", { onclick: () => { ctx.hidden = true; V.bridgeCapture(x.id); } }, `Capture the ${x.name} view`)));
    ctx.hidden = false; ctx.style.left = Math.max(8, r.left - ctx.offsetWidth - 8) + "px"; ctx.style.top = r.top + "px";
