    if (area < 1e-8) return;
    const n = new THREE.Vector3().subVectors(b, a).cross(new THREE.Vector3().subVectors(c, a));
    if (n.lengthSq() < 1e-12) n.subVectors(c, a).cross(new THREE.Vector3().subVectors(d, a));
