    const across = side === "front" ? [xa, xb] : side === "rear" ? [(v, u) => -xb(v, u), (v, u) => -xa(v, u)] : side === "left" ? [za, zb] : [(v, u) => -zb(v, u), (v, u) => -za(v, u)];
    const lv = levels.filter((v) => v <= t + 1e-6);
