      // reveal: the four sides of the recess, facing into the opening
      const rv = (a, b, c, d) => { const g = new THREE.BufferGeometry(); g.setAttribute("position", new THREE.Float32BufferAttribute([...a, ...b, ...c, ...a, ...c, ...d], 3)); g.computeVertexNormals(); const m = new THREE.Mesh(g, mats.wall); m.name = "Reveal"; gr.add(m); };
      rv([q.u0, q.v0, 0], [q.u0, q.v0, -r], [q.u0, q.v1, -r], [q.u0, q.v1, 0]);
      rv([q.u1, q.v1, 0], [q.u1, q.v1, -r], [q.u1, q.v0, -r], [q.u1, q.v0, 0]);
      rv([q.u0, q.v1, 0], [q.u0, q.v1, -r], [q.u1, q.v1, -r], [q.u1, q.v1, 0]);
      if (!q.door) rv([q.u1, q.v0, 0], [q.u1, q.v0, -r], [q.u0, q.v0, -r], [q.u0, q.v0, 0]);
