function panelFront(parts, types) {
  const raised = parts.filter((p) => ({ slat_panel: 0.12, panel: 0.04, open_shelving: 0.25 })[types[p.n]] != null);
  return (x, y) => { const p = raised.find((q) => x >= q.u0 && x <= q.u1 && y >= q.v0 && y <= q.v1); return p ? ({ slat_panel: 0.12, panel: 0.04, open_shelving: 0.25 })[types[p.n]] : 0; };
}

// ---------- AI image step through the normal job flow ----------
async function aiImage(node, prompt, shown) {
  const D = V.D, e = D.imageEngines.find((x) => x.id === V.engines.image && (!x.codex || V.desk)) || D.imageEngines[0];
  const settings = { resolution: "2K", aspect_ratio: "auto", num_images: 1, ...(V.viaGoogle(e.id) ? { provider: "google", fallback: V.cfg.gFallback !== false } : {}) };
  const before = new Set(V.G.nodes.map((n) => n.id));
  await V.submitJob({ kind: "edit", engine: e.id, prompt, shownPrompt: shown, inputs: [node], settings, count: 1 });
  const made = V.G.nodes.find((n) => !before.has(n.id));
  if (!made) throw new Error("couldn't start the AI step");
  for (let i = 0; i < 400; i++) { // up to about 13 minutes
    if (made.status === "done" && made.url) return made;
    if (made.status === "error") throw new Error(made.error || "the AI step failed");
    await new Promise((r) => setTimeout(r, 2000));
  }
  throw new Error("the AI step took too long");
}
