// on a width change, so setting the height doesn't loop
let prW = 0;
new ResizeObserver(() => { if (pr.clientWidth !== prW) { prW = pr.clientWidth; autoSize(); } }).observe(pr);
pr.addEventListener("input", () => { autoSize(); V.activePreset = null; if (!pr.value.trim()) multi = false; drawPresets(); if (V.tab === "image") V.store.set("draft", pr.value); updateMake(); });
// v3.67: undo for prompt changes. Every change made for you (scene, environment, preset, combo, reference, Fill,
// Use prompt, Clear) keeps the prompt it replaced, the last 20; #btnPromptUndo shows while there is one. Typing isn't
