const ENV_IDS = new Set([...groupIds(["Light", "Weather", "Context", "People", "Camera", "Rooms", "Commercial", "Style & furnish", "Life", "Gardens", "Hard landscaping", "Planting", "Water", "Evening", "Seasons"])].filter((id) => !NOT_ENV.has(id)));
