  return await submitJob({ kind: "edit", engine: g4kEngine(), prompt: UP_PROMPT, shownPrompt: "Upscaled ×2 (Google 4K)", name: "Upscaled ×2 (Google 4K)", inputs: [n], firstUrl, settings, count: 1 });
