// ---------- style boards: the AI describes the shared style ----------
const STYLE_SYS = "You are an architectural visualiser. Describe the visual style the reference images share, so an image AI can give that style to a DIFFERENT building or interior: colour palette, materials and textures, light (direction, quality, time of day), sky and weather, atmosphere, styling and props, people and planting, camera and lens feel, and photographic or graphic finish and colour grade. Never describe the buildings' or rooms' forms, layout or architecture. Write one paragraph of 80 to 130 words, as instructions (e.g. \"Warm late-afternoon light...\"). Output only the paragraph.";
async function describe(b, btn) {
  if (!b.imgs.length) return;
  btn.disabled = true; btn.textContent = "Describing…";
  try {
    const imgs = []; for (const [i, s] of b.imgs.slice(0, 6).entries()) imgs.push(await upload(b.id + ":" + i + ":" + s.length, s));
    const r = await V.api("vision", { system: STYLE_SYS, prompt: `These ${imgs.length} reference image${imgs.length > 1 ? "s show" : " shows"} the style wanted for a project${b.name ? ` ("${b.name}")` : ""}. Describe that style.`, images: imgs, fast: true });
    const t = String(r.text || "").trim().replace(/^```\w*\n?|```$/g, "").replace(/^["“]|["”]$/g, "").trim();
    if (!t) throw new Error("the AI sent back nothing");
    b.text = t; V.changed(); paint();
  } catch (e) { V.toast("Couldn't describe the style: " + e.message, true, 0); btn.disabled = false; btn.textContent = "Describe with AI"; }
}
function useAsLook(b) {
  // v3.69 (S7): chosen for the Project look dialog that sent you here: back to it, with what you typed there kept
  if (forLook && V.lookBoardPicked) { forLook = false; return V.lookBoardPicked(b); }
  const L = (V.G.look = V.G.look || { on: false, name: "", ref: null, materials: "", time: "", weather: "", season: "", notes: "" });
  Object.assign(L, { on: true, name: b.name || "Style board", ref: null, refUrl: b.imgs[0] || null, notes: b.text || L.notes, board: b.id });
  V.changed(); V.render(); paint();
  V.toast(`"${b.name || "Style board"}" is now the Project look: every render in this project follows it`, false, 4500);
}

// ---------- sharing the catalogue ----------
async function exportCat() {
  await loadCat();
  // v3.69 (S5): the practice's own saved scenes travel with the catalogue
  const scenes = V.store.get("envs", []) || [];
  if (!CAT.items.length && !CAT.sets.length && !scenes.length) return V.toast("The office catalogue is empty", true);
  const blob = new Blob([JSON.stringify({ app: "Clarman VizLab catalogue", version: 1, exported: new Date().toISOString(), items: CAT.items, sets: CAT.sets, scenes })], { type: "application/json" });
  const url = URL.createObjectURL(blob), d = new Date().toISOString().slice(0, 10);
  // (C1, B4 note) one message: the download names the file and says what went in it
  await V.download(url, `Clarman-catalogue-${d}.vizlab-catalogue.json`, { msg: (f) => `Exported ${CAT.items.length} items, ${CAT.sets.length} collections${scenes.length ? ` and ${scenes.length} saved scene${scenes.length === 1 ? "" : "s"}` : ""} to "${f}" in your Downloads folder. Colleagues use Import in their Library to add them.` }); setTimeout(() => URL.revokeObjectURL(url), 20000);
}
async function importCat(file) {
  try {
    const d = JSON.parse(await file.text()); if (!d || !Array.isArray(d.items)) throw new Error("not a VizLab catalogue file");
    await loadCat(); let ni = 0, ns = 0, nsc = 0;
    for (const it of d.items) { if (!it.id || !it.img) continue; const i = CAT.items.findIndex((x) => x.id === it.id); if (i >= 0) CAT.items[i] = it; else { CAT.items.push(it); ni++; } await putCat(it); }
    for (const s of d.sets || []) { if (!s.id) continue; s.kind = "set"; const i = CAT.sets.findIndex((x) => x.id === s.id); if (i >= 0) CAT.sets[i] = s; else { CAT.sets.push(s); ns++; } await putCat(s); }
    // saved scenes merge by name (one with the same name is updated)
    const sc = (d.scenes || []).filter((x) => x && x.name && x.env), mine = V.store.get("envs", []) || [];
    for (const x of sc) { const i = mine.findIndex((m) => m.name === x.name); if (i >= 0) mine[i] = { name: x.name, env: x.env }; else { mine.push({ name: String(x.name).slice(0, 40), env: x.env }); nsc++; } }
    if (sc.length) { V.store.set("envs", mine); V.envRepaint && V.envRepaint(); V.paintScenePanel && V.paintScenePanel(); }
    paint(); V.toast(`Imported: ${ni} new item${ni === 1 ? "" : "s"}, ${ns} new collection${ns === 1 ? "" : "s"}${sc.length ? ` and ${nsc} new saved scene${nsc === 1 ? "" : "s"} (in Scenes under Your scenes)` : ""} (matching ones updated)`, false, 5000);
  } catch (e) { V.toast("Couldn't import: " + e.message, true, 6000); }
}

