  Object.assign(run, { active: true, stop: false, done: 0, total: todo.length, failed: [], made: [] }); paint();
  if (!todo.length) { run.active = false; await finishSets(chosen); paint(); return V.toast("Those collections are already in the catalogue", false, 3000); }
  let next = 0;
