document.addEventListener("keydown", (e) => { if (e.key === "Escape" && modal && !modal.hidden && (!V.isTopPopup || V.isTopPopup(modal))) { e.preventDefault(); e.stopImmediatePropagation(); modal._shut(); } }, true);
