  const c = mk(W1, H1), x = c.getContext("2d", { willReadFrequently: true }), flat = style === "flat";
  x.fillStyle = "#fff"; x.fillRect(0, 0, W1, H1); x.drawImage(img1, 0, 0, W1, H1); // see-through pictures over white, as uploads are
  const d = x.getImageData(0, 0, W1, H1), p = d.data, u = Math.max(1, 0.0004 * Math.max(W1, H1)), Dt = edgeDist(K, W1, H1, false);
