  for (let y = 0; y < ph; y++) { const o = Math.min(H1 - 1, ((y + 0.5) / sc) | 0) * W1; for (let X = 0; X < pw; X++) P[y * pw + X] = K[o + Math.min(W1 - 1, ((X + 0.5) / sc) | 0)]; }
  const Dp = edgeDist(P, pw, ph, true), seen = new Uint8Array(pw * ph), pieces = [], st = [];
