      if (qx < pw - 1 && !seen[q + 1] && P[q + 1] === s) { seen[q + 1] = 1; st.push(q + 1); }
      if (q >= pw && !seen[q - pw] && P[q - pw] === s) { seen[q - pw] = 1; st.push(q - pw); }
