      x.fillStyle = "#000"; x.font = `bold ${Math.round(dia * 0.6)}px Arial, sans-serif`; x.textAlign = "center"; x.textBaseline = "middle";
      x.fillText(letterOf(l, zOf.get(q.s)), cx, cy + dia * 0.04);
