      if (other) { // the same as another material: the two join up
        const r = await labs(n); if (!r) return;
        const out = r.lab.slice(); for (let i = 0; i < out.length; i++) if (out[i] === z.slot) out[i] = other.slot;
        commit(n, () => { const L = layerOf(n); L.zones = L.zones.filter((q) => q.id !== z.id); L.active = other.id; encode(L, out); });
        return V.toast(`"${z.name}" joined ${letterOf(layerOf(n), zoneOf(layerOf(n), other.id))} · ${other.name}, which has the same material`, false, 4000);
      }
      let moved = null; edit(n, z.id, (L, Z) => { Z.mat = { ...mat }; if (!Z.named) Z.name = mat.name; if (fitWith(L, Z, hs)) moved = Z; L.active = Z.id; });
      if (moved) colourNote(moved);
