    const same = mat && l && l.zones.find((q) => q.mat && sameMat(q.mat, mat));
    if (same) { setActive(same.id); V.toast(`${letterOf(l, same)} · ${same.name} already has that material: carry on painting with it`, false, 3000); return o.then ? clickFill(n, o.then.p, o.then) : null; }
    if (l && l.zones.length >= MAX_ZONES) return V.toast(FULL, true);
    if (o.then) return clickFill(n, o.then.p, o.then, { mat, hs });
