  const name = (await V.ask("Preset name", { value: t.split(/[,.]/)[0].slice(0, 22), text: "Saved under My presets.", ok: "Save" }))?.trim(); if (!name) return;
  try { await V.api("preset_save", { name: name.slice(0, 30), prompt: t, tab: V.tab === "video" ? "video" : "image" }); await V.loadMyPresets(); V.toast(`Saved to My presets: ${name}`); } catch (e) { V.toast(e.message, true, 0); }
