const STRENGTH = { 1: "a subtle", 2: "a noticeable", 3: "a strong" };
const STRENGTH_ADJ = { 1: "subtle", 2: "noticeable", 3: "strong" }; // {a}: before plural words
const VIEWS = [
  ["street", "Street level", "This is a street-level view: the effects are seen from the pavement, with the nearest effects close to the camera."],
  ["elevated", "Elevated", "This is an elevated view: the effects layer with distance across the roofs and streets below."],
  ["aerial", "Aerial", "This is an aerial view: the effects lie in layers over the landscape, with fog and haze pooling in low ground and thickening with distance."],
];

// ---------- realism check: how real environments behave ----------
const has = (E, k, id) => (E[k] || []).includes(id) || E[k] === id;
const SUNLESS = ["overcast", "blue", "night", "moon"];
const SOUTH = ["med", "desert"]; // where the sun can climb higher than in Ireland
const RULES = [
  { when: (E) => ["overcast", "storm"].includes(E.sky) && ["sunny", "golden", "morning", "backlit"].includes(E.light) && E.sky === "overcast", msg: "A full overcast sky hides the sun: there can't be crisp sunlight.", fix: (E) => (E.light = "overcast"), fixLabel: "Use soft overcast light" },
  { when: (E) => E.sky === "stars" && E.light !== "keep" && !["night", "moon"].includes(E.light), msg: "Stars only show in a dark night sky.", fix: (E) => (E.light = "night"), fixLabel: "Use night light" },
  { when: (E) => E.sky === "sunset" && E.light !== "keep" && !["golden", "backlit", "blue"].includes(E.light), msg: "A sunset sky goes with golden-hour light.", fix: (E) => (E.light = "golden"), fixLabel: "Use golden hour" },
  { when: (E) => E.sky === "twilight" && E.light !== "keep" && !["blue", "night", "moon"].includes(E.light), msg: "A twilight sky means the sun has set: blue-hour light.", fix: (E) => (E.light = "blue"), fixLabel: "Use blue hour" },
  { when: (E) => E.sky === "clear" && ["storm", "overcast"].includes(E.light), msg: "A clear sky can't give overcast or storm light.", fix: (E) => (E.sky = E.light === "storm" ? "storm" : "overcast"), fixLabel: "Match the sky to the light" },
  { auto: true, when: (E) => E.sun && SUNLESS.includes(E.light), msg: "There's no direct sun in this light, so a sun position can't show.", fix: (E) => (E.sun = null), fixLabel: "Clear the sun position" },
  { auto: true, when: (E) => E.sun && E.light === "golden" && E.sun.el > 14, msg: "At golden hour the sun is low: under about 12° above the horizon.", fix: (E) => (E.sun.el = 7), fixLabel: "Lower the sun to 7°" },
  { auto: true, when: (E) => E.sun && E.light === "morning" && (E.sun.el < 5 || E.sun.el > 32), msg: "Low morning sun sits roughly 8° to 30° above the horizon.", fix: (E) => (E.sun.el = 18), fixLabel: "Set the sun to 18°" },
  { auto: true, when: (E) => E.sun && E.light === "sunny" && E.sun.el < 30, msg: "Bright midday sun is high in the sky, not near the horizon.", fix: (E) => (E.sun.el = 50), fixLabel: "Raise the sun to 50°" },
  { auto: true, when: (E) => E.sun && E.light === "backlit" && Math.abs(wrap(E.sun.az)) > 70, msg: "Backlit means the sun is ahead of the camera, behind the building.", fix: (E) => (E.sun.az = 0), fixLabel: "Put the sun ahead" },
  { auto: true, when: (E) => E.sun && E.sun.el > 60 && !SOUTH.includes(E.setting), msg: "In Ireland and the UK the sun never climbs above about 60° (midsummer noon).", fix: (E) => (E.sun.el = 55), fixLabel: "Lower the sun to 55°" },
  { auto: true, when: (E) => E.sun && E.sun.frame && !sunInFrame(E, E.sun), msg: "The sun is marked as in the shot, but from here it would be out of frame.", fix: (E) => (E.sun.frame = false), fixLabel: "Keep it out of shot" },
  { when: (E) => has(E, "atmos", "heat") && (has(E, "surface", "snow") || has(E, "surface", "frost") || has(E, "atmos", "snowfall")), msg: "Heat shimmer can't happen with snow or frost: it needs hot ground.", fix: (E) => drop(E, "atmos", "heat") , fixLabel: "Remove heat shimmer" },
  { when: (E) => has(E, "atmos", "heat") && E.light !== "keep" && !["sunny", "golden", "morning", "backlit"].includes(E.light), msg: "Heat shimmer only rises off ground heated by strong sun.", fix: (E) => (E.light = "sunny"), fixLabel: "Use bright midday sun" },
  { when: (E) => has(E, "atmos", "rays") && E.light !== "keep" && !["sunny", "golden", "morning", "backlit", "storm"].includes(E.light), msg: "God rays need direct sun breaking through.", fix: (E) => (E.light = "golden"), fixLabel: "Use golden hour" },
  { auto: true, when: (E) => has(E, "atmos", "rays") && !["haze", "fog", "mist", "dust", "smoke", "steam"].some((x) => has(E, "atmos", x)), msg: "God rays only show in hazy, misty or dusty air.", fix: (E) => add(E, "atmos", "haze", 1), fixLabel: "Add subtle haze" },
  { when: (E) => (has(E, "atmos", "fog") || has(E, "atmos", "mist")) && E.light === "sunny", msg: "Fog and mist burn off in strong midday sun.", fix: (E) => (E.light = "morning"), fixLabel: "Use low morning sun" },
  { auto: true, when: (E) => (has(E, "atmos", "rain") || has(E, "atmos", "drizzle")) && !has(E, "surface", "wet"), msg: "In rain every surface is wet.", fix: (E) => add(E, "surface", "wet"), fixLabel: "Add wet surfaces" },
  { when: (E) => (has(E, "atmos", "rain") || has(E, "atmos", "drizzle")) && ["sunny", "golden", "morning"].includes(E.light), msg: "Rain with full sun is a rare sun shower: overcast or breaking storm light is more believable.", fix: (E) => (E.light = "storm"), fixLabel: "Use breaking storm light" },
  { auto: true, when: (E) => has(E, "atmos", "snowfall") && !has(E, "surface", "snow"), msg: "Falling snow settles: add a layer of snow on the ground and roofs.", fix: (E) => add(E, "surface", "snow"), fixLabel: "Add snow cover" },
  { when: (E) => has(E, "surface", "snow") && (has(E, "surface", "dusty") || has(E, "surface", "lush")), msg: "Snow cover doesn't go with dusty ground or lush summer planting.", fix: (E) => { drop(E, "surface", "dusty"); drop(E, "surface", "lush"); }, fixLabel: "Remove dusty / lush" },
  { when: (E) => has(E, "surface", "frost") && ["sunny", "golden", "backlit"].includes(E.light), msg: "Frost melts in the sun: it lasts in early morning light or in shade.", fix: (E) => (E.light = "morning"), fixLabel: "Use low morning sun" },
  { when: (E) => has(E, "surface", "dusty") && (has(E, "surface", "wet") || has(E, "surface", "puddles")), msg: "Ground can't be dusty and wet at once.", fix: (E) => drop(E, "surface", "dusty"), fixLabel: "Remove dusty ground" },
  { when: (E) => has(E, "life", "empty") && ["few", "busy", "traffic", "cyclists", "dogs"].some((x) => has(E, "life", x)), msg: "\"No one about\" clashes with the people or traffic you've added.", fix: (E) => drop(E, "life", "empty"), fixLabel: "Remove \"No one about\"" },
  { when: (E) => has(E, "atmos", "spray") && !["coast", "docks", "keep"].includes(E.setting), msg: "Sea spray only happens by the sea.", fix: (E) => drop(E, "atmos", "spray"), fixLabel: "Remove sea spray" },
  { when: (E) => has(E, "atmos", "heat") && E.view === "aerial", msg: "Heat shimmer is only visible close to the ground at street level.", fix: (E) => (E.view = "street"), fixLabel: "Use a street-level view" },
  { when: (E) => has(E, "grade", "bw") && ["warm", "tealorange", "film", "brochure", "nordic"].some((x) => has(E, "grade", x)), msg: "Black & white replaces the colour grades you've chosen.", fix: (E) => (E.grade = E.grade.filter((x) => ["bw", "grain", "vignette"].includes(x))), fixLabel: "Keep just black & white" },
];
function add(E, k, id, s = 2) { if (!E[k]) E[k] = []; if (!E[k].includes(id)) E[k].push(id); if (["atmos", "sunin"].includes(k)) E.str[id] = E.str[id] || s; }
function drop(E, k, id) { E[k] = (E[k] || []).filter((x) => x !== id); delete E.str[id]; }

