function rememberMode(m) {
  modeOf.set(V.G, m); V.store.set("sceneMode", m);
  if (V.project && V.project.id) { const all = V.store.get("sceneModes", {}) || {}; if (all[V.project.id] !== m) { all[V.project.id] = m; V.store.set("sceneModes", all); } }
}
const furnitureInUse = () => ((V.G.library && V.G.library.items) || []).some((i) => i.kind === "furniture" && i.use);

// v3.67: the scene goes into its own slot (a chip by the prompt), not into the prompt box. The furniture the last scene
// put in goes out, this one's collection comes in (its prompt goes with the scene), and Undo puts everything back.
// v3.69: your own products in renders (not put there by a scene) stay, and the scene's furniture is offered instead of
