const page = () => S.pages[cur];
const frameOf = (id) => page().frames.find((f) => f.id === id);
const push = () => { hist.push(JSON.stringify(S)); if (hist.length > 60) hist.shift(); fut.length = 0; };
function commit(fn, noHist) { if (!noHist) push(); fn(); V.G.sheets = S; V.changed(); paint(); }
function undo() { if (!hist.length) return; fut.push(JSON.stringify(S)); S = JSON.parse(hist.pop()); V.G.sheets = S; cur = Math.min(cur, S.pages.length - 1); sel = null; V.changed(); paint(); }
function redo() { if (!fut.length) return; hist.push(JSON.stringify(S)); S = JSON.parse(fut.pop()); V.G.sheets = S; cur = Math.min(cur, S.pages.length - 1); sel = null; V.changed(); paint(); }
