  const hint = modal.querySelector(".shhint");
  hint.textContent = tool === "leader" ? "Leader: drag from the point you're noting to where the text should go, then type. Esc when done." : tool === "dim" ? "Dimension: drag between two points (it locks level or upright; Alt for any angle). Type the real length once and the rest measure themselves. Esc when done." : selM ? "Drag to move · drag the dots to change · click the text to edit · Delete removes" : adjust ? "Moving the picture inside its frame: drag it, wheel to zoom. Double-click or Esc when done." : sel ? "Drag to move · handles resize · double-click a picture to move it inside its frame · Delete removes" : "";
