  guides.forEach(([x1, y1, x2, y2]) => (s += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#ff3d8b" stroke-width="1" vector-effect="non-scaling-stroke"/>`));
