  pop.append(h("div", { class: "ralhead" }, h("b", {}, "RAL Classic colours"), h("button", { class: "lx", onclick: closeRAL }, "×")), search,
    ...(recent.length ? [h("div", { class: "ralrecent" }, h("small", {}, "Recent"), ...recent.map(sw))] : []), chips, grid, name, // (Element.append writes a null as the word "null")
    h("p", { class: "hint ralnote" }, "Screen colours are approximate. Check a physical RAL chart before specifying."));
