function choose(r) {
  V.store.set("ralRecent", [r.code, ...V.store.get("ralRecent", []).filter((c) => c !== r.code)].slice(0, 9));
  const f = ralPick; closeRAL(); f && f(r);
}
function closeRAL() { pop.hidden = true; ralPick = null; }
