// v3.69 (J-planning-S2): your own words from "Anything to add?", as a sentence of their own after the brief
const withExtra = (out) => { const x = (F.extra || "").trim(); if (!x) return out; const t = /[.!?]$/.test(x) ? x : x + "."; return out ? out.replace(/\s*$/, "") + (/[.!?]$/.test(out.trim()) ? " " : ". ") + t : t; };
