// file and folder names: as typed, without slashes or control characters (Drive itself allows the rest)
const clean = (s) => String(s || "").replace(/[\\/\u0000-\u001f]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 100) || "Picture";
