const KIND_WORD = { render: "Render", edit: "Edit", create: "New picture", upscale: "Upscale", video: "Video", vupscale: "Upscaled video", "3d": "3D model", world: "3D world" };
const kindWord = (j) => KIND_WORD[V.kindOf(j.kind, j.settings)] || "Result";
