  if (F.q) { const hay = [V.historyPrompt(j), j.prompt, jobProjName(j), j.engine, V.engineName(j.engine), sceneOf(j), kindWord(j)].join(" ").toLowerCase(); if (!F.q.toLowerCase().split(/\s+/).every((w) => hay.includes(w))) return false; }
